from pathlib import Path
import re, yaml, hashlib
p=Path('docs/specs/arch/ARCH-001.md')
s=p.read_text()
f=yaml.safe_load(s.split('---',2)[1])
blocks=re.findall(r'"'^```yaml items'"\\n(.*?)"'^```'"',s,re.M|re.S)
items={}
for block in blocks:
 d=yaml.safe_load(block)
 assert len(d)==1
 items.update(d)
prd=Path('docs/specs/prd/PRD-001.md').read_text()
reqs={}
for block in re.findall(r'"'^```yaml items'"\\n(.*?)"'^```'"',prd,re.M|re.S):
 for key, values in yaml.safe_load(block).items():
  if key in ('functional_requirements','non_functional_requirements'):
   reqs.update({i['id']:i for i in values if i['status']=='active'})
expected_keys='id type title status version created updated owner authors generated_by reviewed_by approved_by approved_on upstream supersedes superseded_by blocked_by system outcome inspection_scope'.split()
assert list(f)==expected_keys
assert f['id']==p.stem and f['type']=='arch' and f['status']=='draft' and f['version']==1
assert str(f['created'])==str(f['updated'])=='2026-09-28'
assert f['owner']=='Priya Nair' and f['authors']==['Priya Nair','codex']
assert f['reviewed_by']==[] and f['approved_by']=='' and f['approved_on'] is None
assert f['supersedes']==[] and f['superseded_by'] is None and f['blocked_by']==[]
assert f['outcome'] is None and f['inspection_scope']==[]
assert f['upstream']==[dict(id='PRD-001',relation='informed_by',version=1,hash=None)]
assert list(items)==['components','decisions','evidence']
fields={
 'components':'id status name responsibility owns_data interacts_with deployment upstream'.split(),
 'decisions':'id status question blocking state resolved_by notes upstream'.split(),
 'evidence':'id status source kind finding classification'.split()}
for collection,prefix in [('components','CMP'),('decisions','DEC'),('evidence','EVD')]:
 assert items[collection]
 for n,item in enumerate(items[collection],1):
  assert list(item)==fields[collection]
  assert item['id']==f'{prefix}-{n:02d}' and item['status']=='active'
  for link in item.get('upstream',[]):
   assert list(link)==['id','item','relation','version','hash']
   assert link['id']=='PRD-001' and link['item'] in reqs and link['version']==1
   assert link['relation']=='informed_by' and link['hash'] is None
   if collection=='components': assert link['item'].startswith('NFR-')
for d in items['decisions']:
 assert d['blocking'] is True and d['state']=='open' and d['resolved_by']==[] and d['upstream']
assert 'identity provider' in items['decisions'][0]['question']
assert 'FR-001' in {u['item'] for u in items['decisions'][0]['upstream']}
assert {'FR-001','NFR-001'} <= {u['item'] for u in items['decisions'][1]['upstream']}
assert set(reqs)=={u['item'] for u in items['decisions'][6]['upstream']}
assert items['evidence'][0]['source']=='PRD-001' and items['evidence'][0]['kind']=='prd'
assert items['evidence'][0]['classification']=='context' and items['evidence'][0]['finding'].startswith('Version 1, status approved:')
assert not list(Path('docs/specs/adr').glob('ADR-*.md'))
assert len(list(Path('docs/specs/arch').glob('ARCH-*.md')))==1
expected_headings=['1. Context and scope','2. Quality drivers','3. Components','4. Architectural questions','5. Evidence inspected','6. Deployment','7. Requirement changes proposed to the PRD owner','8. Open questions','Change Log']
assert re.findall(r'"'^## (.+)$'"',s,re.M)==expected_headings
assert '"'```mermaid'"\\nflowchart' in s
assert not any(x in s for x in ['<"'!--'"','ARCH-000','PRD-000','YYYY-MM-DD','<component>'])
assert '[NEEDS CLARIFICATION: host model/session identity unavailable]' in s
assert '# --- arch-specific ---\\nsystem:' in s
for heading in expected_headings[6:8]:
 section=s.split('## '+heading+'\\n',1)[1].split('\\n## ',1)[0]
 assert re.search(r'"'^- '"',section,re.M)
# Verify quotation style and allowed sequence styles in the actual YAML nodes.
text_fields={'title','owner','system','tool','model','session','approved_by','name','responsibility','deployment','question','notes','source','finding'}
text_lists={'authors','owns_data','interacts_with','inspection_scope'}
def walk(node,key=None):
 if isinstance(node,yaml.MappingNode):
  for k,v in node.value: walk(v,k.value)
 elif isinstance(node,yaml.SequenceNode):
  if node.value:
   assert bool(node.flow_style)==(key=='resolved_by'), (key,'sequence style')
  for child in node.value:
   if key in text_lists: assert child.style=='\"', (key,'quote style')
   walk(child)
 elif isinstance(node,yaml.ScalarNode) and key in text_fields and node.tag.endswith(':str'):
  assert node.style=='\"', (key,'quote style')
walk(yaml.compose(s.split('---',2)[1]))
for block in blocks: walk(yaml.compose(block))
last=[line for line in s.splitlines() if line.startswith('| 1 |')][-1]
assert 'codex (session unknown)' in last
assert last.split('|')[4].strip().endswith('Policy resolution: interview.max_calls=8 (default); architecture.mandated_platforms=none (default); quality.required_categories=floor only (default)')
print('Candidate SHA256: '+hashlib.sha256(p.read_bytes()).hexdigest())
print('PASS: self-checks 1, 2, 4-15 (structural checks plus manual scope, requirement relevance and decision-authority review).')
print('PASS: 3 components, 8 open decisions, 1 PRD evidence item; all 6 active requirements linked; no ADRs.')
print('BLOCKED: self-check 3; exact host model/session identity unavailable. Tool, approval and hash fields otherwise pass.')
print('NOT_RUN: readiness handoff, because provenance validation is unresolved. ADR checks 16-18 are not applicable.')
